package com.kvs.exam.config;

/**
 * Permission checks for this service's endpoints: ExamPerms.X is "hasAuthority('<code>')" for @PreAuthorize.
 * Generated by database/rbac/rewrite_preauthorize.py from the RBAC catalogue (ms-core rbac/permissions.json);
 * which roles hold each code is decided by the catalogue and by each school's custom roles, not here.
 */
public final class ExamPerms {

    private ExamPerms() {
    }

    public static final String STUDENTS_MANAGE = "hasAuthority('exam.students.manage')";
    public static final String STUDENTS_VIEW = "hasAuthority('exam.students.view')";
    public static final String TEMPLATES_MANAGE = "hasAuthority('exam.templates.manage')";
    public static final String TERMS_2_MANAGE = "hasAuthority('exam.terms-2.manage')";
    public static final String TERMS_2_VIEW = "hasAuthority('exam.terms-2.view')";
    public static final String TERMS_3_MANAGE = "hasAuthority('exam.terms-3.manage')";
    public static final String TERMS_3_VIEW = "hasAuthority('exam.terms-3.view')";
    public static final String TERMS_MANAGE = "hasAuthority('exam.terms.manage')";
    public static final String TERMS_VIEW = "hasAuthority('exam.terms.view')";

    /** Not an endpoint check: see any student's marks and results, not only one's own children's (ExamAccess) */
    public static final String RESULTS_ANY_STUDENT = "exam.results.any-student";
}
